#ifndef INSTRUCTION_HPP
#define INSTRUCTION_HPP

#include <iostream>
#include <string>

class InvalidAccess : public std::runtime_error {
public:
    InvalidAccess(const std::string& message) : std::runtime_error(message) {}
};

enum Type {
    R, I, S, B, U, J
};

using Instruction = unsigned int;
using Immediate = int32_t; // Assuming int32_t for immediate values

class InstructionBase {
public:
    unsigned int opcode;
    unsigned int rs1;
    unsigned int rs2;
    unsigned int rd;
    unsigned int funct3;
    unsigned int funct7;
    Immediate imm;
    Instruction inst;
    Type t;

    InstructionBase() : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(0), t(Type::R) {}

    InstructionBase(unsigned int instruction) : opcode(0), rs1(0), rs2(0), rd(0), funct3(0), funct7(0), imm(0), inst(-1), t(Type::I) {
        // Placeholder constructor for immediate-type NOP
    }

    static unsigned int bin_mask(int digits) {
        return (1 << digits) - 1;
    }

    static unsigned int get_digits(unsigned int n, int hi, int lo) {
        return (n >> lo) & bin_mask(hi - lo + 1);
    }

    static unsigned int expand_digit(unsigned int digit, int lo) {
        if (digit != 0) {
            return 1 << lo;
        } else {
            return 0;
        }
    }

    bool is_nop() const {
        return inst == -1;
    }

    bool is_valid(const std::string &key) const {
        switch (t) {
            case Type::R:
                return key != "imm";
            case Type::I:
                return key != "rs2" && key != "funct7";
            case Type::S:
                return key != "rd" && key != "funct7";
            case Type::B:
                return key != "rd" && key != "funct7";
            case Type::U:
                return key != "rs1" && key != "rs2" && key != "funct3" && key != "funct7";
            case Type::J:
                return key != "rs1" && key != "rs2" && key != "funct3" && key != "funct7";
            default:
                return false;
        }
    }

    void verify(const std::string &key) const {
        if (!is_valid(key)) {
            throw InvalidAccess("Invalid access to field: " + key);
        }
    }

    virtual void debug() const {
        std::cout << "0x" << std::hex << inst << ":";
        switch (t) {
            case Type::R:
                std::cout << " R-type";
                break;
            case Type::I:
                std::cout << " I-type";
                break;
            case Type::S:
                std::cout << " S-type";
                break;
            case Type::B:
                std::cout << " B-type";
                break;
            case Type::U:
                std::cout << " U-type";
                break;
            case Type::J:
                std::cout << " J-type";
                break;
        }
        std::cout << std::endl;
    }

    bool has_op1() const {
        return t != Type::U && t != Type::J;
    }

    bool has_op2() const {
        return t == Type::R || t == Type::S || t == Type::B;
    }
};

class InstructionR : public InstructionBase {
public:
    InstructionR(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        funct7 = get_digits(inst, 31, 25);
        t = Type::R;
    }
};

class InstructionI : public InstructionBase {
public:
    InstructionI(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        imm = (int32_t)get_digits(inst, 31, 20);
        t = Type::I;
    }
};

class InstructionS : public InstructionBase {
public:
    InstructionS(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        imm = (int32_t)get_digits(inst, 31, 20);
        t = Type::S;
    }
};

class InstructionB : public InstructionBase {
public:
    InstructionB(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        funct3 = get_digits(inst, 14, 12);
        rs1 = get_digits(inst, 19, 15);
        rs2 = get_digits(inst, 24, 20);
        imm = (int32_t)get_digits(inst, 31, 20);
        t = Type::B;
    }
};

class InstructionU : public InstructionBase {
public:
    InstructionU(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = (int32_t)get_digits(inst, 31, 12);
        t = Type::U;
    }
};

class InstructionJ : public InstructionBase {
public:
    InstructionJ(Instruction inst) : InstructionBase(inst) {
        opcode = get_digits(inst, 6, 0);
        rd = get_digits(inst, 11, 7);
        imm = (int32_t)get_digits(inst, 31, 12);
        t = Type::J;
    }
};

#endif // INSTRUCTION_HPP
